using System; using System.IO; using System.Reflection; using System.Runtime.CompilerServices;
public class CacheProxy : DispatchProxy { public static bool Saved; protected override object Invoke(MethodInfo method, object[] args) { if (method.IsGenericMethod && method.GetGenericArguments()[0] == typeof(bool)) return Saved; return null; } }
class RuntimeProbe {
